1	export const FOR_EACH_MODES = new Set(['addPrompt', 'compact', 'newConversation']);
2	export const FOR_EACH_FAILURE_POLICIES = new Set(['logAndContinue', 'stopOnFirstFailure']);
3	
4	const DATA_PLACEHOLDER_PATTERN = /\{\{\s*data\s+([^{}]+?)\s*\}\}/gu;
5	
6	function validateJsonValue(value, fieldName) {
7	    if (value === null || typeof value === 'string' || typeof value === 'boolean') return value;
8	    if (typeof value === 'number' && Number.isFinite(value)) return value;
9	    if (Array.isArray(value)) return value.map((entry, index) => validateJsonValue(entry, `${fieldName}[${index}]`));
10	    if (!value || typeof value !== 'object') throw new Error(`Invalid ${fieldName}`);
11	
12	    return Object.fromEntries(Object.entries(value).map(([key, entry]) => [key, validateJsonValue(entry, `${fieldName}.${key}`)]));
13	}
14	
15	/** Validate one conversation-owned for-each configuration. */
16	export function validateForEachConfig(value, fieldName = 'forEach') {
17	    if (!value || typeof value !== 'object' || Array.isArray(value)) throw new Error(`Invalid ${fieldName}`);
18	    const allowedFields = new Set(['dataPath', 'failurePolicy', 'fileName', 'mode', 'startIndex', 'value']);
19	    const unsupportedField = Object.keys(value).find((name) => !allowedFields.has(name));
20	    if (unsupportedField) throw new Error(`Unsupported ${fieldName} field: ${unsupportedField}`);
21	    if (value.dataPath !== undefined && typeof value.dataPath !== 'string') throw new Error(`Invalid ${fieldName}.dataPath`);
22	    if (typeof value.fileName !== 'string' || value.fileName.length === 0) throw new Error(`Invalid ${fieldName}.fileName`);
23	    if (!FOR_EACH_MODES.has(value.mode)) throw new Error(`Invalid ${fieldName}.mode`);
24	    if (!FOR_EACH_FAILURE_POLICIES.has(value.failurePolicy)) throw new Error(`Invalid ${fieldName}.failurePolicy`);
25	    const startIndex = value.startIndex === undefined ? 0 : value.startIndex;
26	    if (typeof startIndex !== 'number' || !Number.isSafeInteger(startIndex) || startIndex < 0) {
27	        throw new Error(`Invalid ${fieldName}.startIndex`);
28	    }
29	
30	    return {
31	        ...(value.dataPath !== undefined ? { dataPath: value.dataPath } : {}),
32	        failurePolicy: value.failurePolicy,
33	        fileName: value.fileName,
34	        mode: value.mode,
35	        startIndex,
36	        value: validateJsonValue(value.value, `${fieldName}.value`),
37	    };
38	}
39	
40	function dataPathValue(record, path) {
41	    const segments = path.split('.');
42	    if (segments.some((segment) => segment.length === 0)) throw new Error(`Missing for-each data path: ${path}`);
43	    let current = record;
44	    for (const segment of segments) {
45	        if (Array.isArray(current)) {
46	            if (!/^\d+$/u.test(segment)) throw new Error(`Missing for-each data path: ${path}`);
47	            const index = Number(segment);
48	            if (!Number.isSafeInteger(index) || index >= current.length) throw new Error(`Missing for-each data path: ${path}`);
49	            current = current[index];
50	            continue;
51	        }
52	        if (!current || typeof current !== 'object' || !Object.hasOwn(current, segment)) {
53	            throw new Error(`Missing for-each data path: ${path}`);
54	        }
55	        current = current[segment];
56	    }
57	
58	    return current;
59	}
60	
61	/**
62	 * Ordered loop records for one JSON root: a root array iterates directly, a selector picks an array
63	 * inside any other root, and without a selector the root is one record.
64	 */
65	export function forEachRecords(value, dataPath = '') {
66	    if (Array.isArray(value)) return [...value];
67	    const path = dataPath.trim();
68	    if (path.length === 0) return [value];
69	    const selected = dataPathValue(value, path);
70	    if (!Array.isArray(selected)) throw new Error(`For-each data path is not a list: ${path}`);
71	
72	    return [...selected];
73	}
74	
75	/** Resolve data placeholders against one record. Strings remain raw; other JSON values serialize. */
76	export function resolveDataPlaceholders(text, record) {
77	    return text.replace(DATA_PLACEHOLDER_PATTERN, (_match, path) => {
78	        const value = dataPathValue(record, path.trim());
79	
80	        return typeof value === 'string' ? value : JSON.stringify(value);
81	    });
82	}
