            .toBe(`Record: ${JSON.stringify(record, null, 2)}\nCity: Brussels\nDetails: {"enabled":true}`);
    });

    it('inserts dollar sequences and placeholder-like record content literally', () => {
        const record = { content: '$& $` $\' {{data other}}', other: 'changed' };

